CREATE TABLE kanna_schema(version INTEGER PRIMARY KEY);
CREATE TABLE warnings(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,chat_id BIGINT NOT NULL,user_id BIGINT NOT NULL,author_id BIGINT,reason TEXT NOT NULL,time TEXT NOT NULL,event_id TEXT NOT NULL,actor_username TEXT,target_username TEXT,UNIQUE(chat_id,event_id));
CREATE INDEX warning_member ON warnings(chat_id,user_id);
CREATE TABLE roles(chat_id BIGINT NOT NULL,user_id BIGINT NOT NULL,role TEXT NOT NULL,actor_id BIGINT NOT NULL,time TEXT NOT NULL,PRIMARY KEY(chat_id,user_id));
CREATE TABLE rules(chat_id BIGINT NOT NULL,code TEXT NOT NULL,version INTEGER NOT NULL,snapshot TEXT NOT NULL,actor_id BIGINT NOT NULL,time TEXT NOT NULL,PRIMARY KEY(chat_id,code,version));
CREATE TABLE infractions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,warning_id BIGINT NOT NULL UNIQUE REFERENCES warnings(id),rule_code TEXT,rule_version INTEGER,weight INTEGER CHECK(weight BETWEEN 0 AND 4),snapshot TEXT,cancel_time TEXT,cancel_actor BIGINT,cancel_reason TEXT);
CREATE TABLE sanctions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,chat_id BIGINT NOT NULL,event_id TEXT NOT NULL,action TEXT NOT NULL,actor_id BIGINT NOT NULL,target_id BIGINT NOT NULL,rule_code TEXT,rule_version INTEGER,reason TEXT NOT NULL,status TEXT NOT NULL,detail TEXT NOT NULL,time TEXT NOT NULL,actor_username TEXT,target_username TEXT,UNIQUE(chat_id,event_id,action));
CREATE TABLE role_changes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,chat_id BIGINT NOT NULL,user_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,previous_role TEXT NOT NULL,new_role TEXT NOT NULL,cause TEXT NOT NULL,time TEXT NOT NULL);
CREATE TABLE identities(chat_id BIGINT NOT NULL,user_id BIGINT NOT NULL,username TEXT,observed_at DOUBLE PRECISION NOT NULL,PRIMARY KEY(chat_id,user_id));
CREATE UNIQUE INDEX identity_username ON identities(chat_id,username) WHERE username IS NOT NULL;
CREATE TABLE detections(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,chat_id BIGINT NOT NULL,message_id BIGINT NOT NULL,user_id BIGINT NOT NULL,rules TEXT NOT NULL,status TEXT NOT NULL,reviewer BIGINT,reason TEXT,outcome TEXT,time TEXT NOT NULL,UNIQUE(chat_id,message_id));
CREATE TABLE evidence(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,chat_id BIGINT NOT NULL,message_id BIGINT NOT NULL,user_id BIGINT,username TEXT,captured_at TEXT NOT NULL,payload TEXT,availability TEXT NOT NULL,removed_at TEXT,removed_by BIGINT,removal_reason TEXT,UNIQUE(chat_id,message_id));
CREATE TABLE evidence_actions(evidence_id BIGINT NOT NULL REFERENCES evidence(id),event_id TEXT NOT NULL,action TEXT NOT NULL,PRIMARY KEY(evidence_id,event_id,action));
CREATE VIEW catalogo_regras AS SELECT r.chat_id AS grupo_id,r.code AS codigo,r.version AS versao,r.snapshot::jsonb->>'name' AS nome,r.snapshot::jsonb->>'description' AS descricao,r.snapshot::jsonb->>'level' AS nivel,(r.snapshot::jsonb->>'weight')::integer AS peso,(r.snapshot::jsonb->>'active')::boolean AS ativa,r.snapshot::jsonb->'actions' AS acoes,r.time AS criada_em FROM rules r WHERE r.version=(SELECT MAX(x.version) FROM rules x WHERE x.chat_id=r.chat_id AND x.code=r.code);
CREATE VIEW historico_advertencias AS SELECT i.id AS registro,w.chat_id AS grupo_id,w.user_id AS alvo_id,w.target_username AS alvo_username,w.author_id AS autor_id,w.actor_username AS autor_username,w.time AS aplicada_em,i.rule_code AS regra,i.rule_version AS versao,i.snapshot::jsonb->>'name' AS nome_regra,i.snapshot::jsonb->>'description' AS descricao_aplicada,i.weight AS peso,w.reason AS motivo,CASE WHEN i.cancel_time IS NULL THEN 'valida' ELSE 'cancelada' END AS estado,i.cancel_time AS cancelada_em,i.cancel_actor AS cancelada_por,i.cancel_reason AS motivo_cancelamento FROM warnings w JOIN infractions i ON w.id=i.warning_id;
CREATE VIEW acoes_moderacao AS SELECT id AS registro,chat_id AS grupo_id,actor_id AS autor_id,actor_username AS autor_username,target_id AS alvo_id,target_username AS alvo_username,action AS acao,reason AS motivo,status AS resultado,detail AS detalhe,time AS data FROM sanctions;
CREATE VIEW evidencias AS SELECT * FROM evidence;
